const {fitDataAsync, OPTIMIZERS} = DataScience;
let nn = NeuralNet.builder().input(2).positionalEncoding(6).layer(25).layer(25).layer(1,
NeuralNet.ACTIVATIONS.sigmoid).build();
const samples = await IO.loadMNIST();
const sample = samples[31];
// MNIST is 28x28 = 784 1-array we want to map it into a [0,1]^2
const trainXs = Array.from(sample).map((_, i) => [(i % 28) / 27, 1.0 - Math.floor(i / 28) / 27]);
const image = IO.paintMNIST([sample, new Float32Array(sample.length)]);
const paintImage = image.update;
const updateImage = theta => {
    nn.setWeights(theta);
    paintImage([sample, Float32Array.from(trainXs.map(([x, y]) => nn.eval([x, y])))]);
};

setTimeout(async () => {
    const {theta} = await fitDataAsync(trainXs, trainXs.map((_, i) => sample[i]), nn.model, {
        epochs: 1000,
        batch: 10,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.01}),
        continuationEvery: 25,
        continuationFn: ({theta}) => updateImage(theta),
    });
    thetaA = theta;
    updateImage(theta);
});
image;
